118	        // 业务冲突失败（重复创建）也不占新键：先制造已存在实验，再用新键冲突，
119	        // 再用该键创建另一个实验应成功。
120	        ResponseEntity<String> conflict = post("/api/experiments/IDEM-3",
121	                headers("c1", "COORDINATOR", "idem-key-4"), "{\"blockCount\":2}");
122	        assertEquals(409, conflict.getStatusCode().value());
123	        assertEquals(0, jdbc.queryForObject(
124	                "SELECT COUNT(*) FROM idempotent_request WHERE request_id = 'idem-key-4'",
125	                Integer.class));
126	        assertEquals(201, post("/api/experiments/IDEM-4",
127	                headers("c1", "COORDINATOR", "idem-key-4"), "{\"blockCount\":2}")
128	                .getStatusCode().value());
